<?php
require_once __DIR__.'/../includes/bootstrap.php';require_customer();$msg='';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['product_id']??0);$q=max(1,(int)($_POST['quantity']??1));if($action==='add'){try{$s=$pdo->prepare('SELECT quantity_in_stock,status FROM products WHERE product_id=?');$s->execute([$id]);$p=$s->fetch();if(!$p||!product_is_available($p))$errors[]='This item is currently out of stock.';elseif($q>(int)$p['quantity_in_stock'])$errors[]='Only '.(int)$p['quantity_in_stock'].' item(s) are currently available.';else{$_SESSION['cart'][$id]=min($q,(int)$p['quantity_in_stock']);$_SESSION['cart_added_at'][$id]=$_SESSION['cart_added_at'][$id]??time();$msg='Item added to your cart.';}}catch(Throwable $e){$errors[]='The cart could not be updated.';}}elseif($action==='remove'){unset($_SESSION['cart'][$id],$_SESSION['cart_added_at'][$id]);$msg='Item removed from your cart.';}elseif($action==='update'){if(isset($_SESSION['cart'][$id])){$_SESSION['cart'][$id]=$q;$msg='Cart quantity updated. Stock is rechecked below.';}}}
$cart=$_SESSION['cart']??[];$ids=array_keys($cart);$items=[];$subtotal=0;$blocked=false;
if($ids){$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.category_id=p.category_id WHERE p.product_id IN ($in)");$s->execute($ids);$items=$s->fetchAll();foreach($items as $p){$stock=(int)$p['quantity_in_stock'];$available=product_is_available($p);if(!$available){$blocked=true;continue;}$_SESSION['cart'][$p['product_id']]=min((int)$_SESSION['cart'][$p['product_id']],$stock);$subtotal+=(float)$p['unit_price']*(int)$_SESSION['cart'][$p['product_id']];}}
$title='Your Cart';require __DIR__.'/../includes/header.php';?><div class="section-head"><div><span class="eyebrow">SHOPPING CART</span><h1>Your cart</h1><p>Stock is checked against the live database whenever this page opens.</p></div><a class="btn ghost" href="/">Continue shopping</a></div><?php if($msg):?><div class="flash success"><?=e($msg)?></div><?php endif;?><?php foreach($errors as $x):?><div class="errors"><?=e($x)?></div><?php endforeach;?><?php if($blocked):?><div class="flash warning"><strong>Some cart items are unavailable.</strong> They remain visible below for transparency, but checkout is blocked until you remove them or management restores stock.</div><?php endif;?><div class="cart-layout"><section class="panel"><?php if(!$items):?><div class="empty"><h2>Your cart is empty</h2><a class="btn primary" href="/">Shop products</a></div><?php else:?><?php foreach($items as $p):$stock=(int)$p['quantity_in_stock'];$available=product_is_available($p);$added=(int)($_SESSION['cart_added_at'][$p['product_id']]??time());$age=max(0,time()-$added);?><div class="cart-item <?=$available?'':'out-stock cart-unavailable'?>"><img src="<?=e(product_image($p))?>" alt="<?=e($p['product_name'])?>"><div><h3><?=e($p['product_name'])?></h3><span class="stock-label"><?=$available?'IN STOCK · '.$stock.' available':'OUT OF STOCK'?></span><p><?=money((float)$p['unit_price'])?> × <?= (int)($_SESSION['cart'][$p['product_id']]??1)?></p><?php if($age>=86400):?><div class="cart-reminder">This item has been in your cart for more than a day. Stock and availability can change. Please complete your order soon.</div><?php endif;?></div><div><?php if($available):?><form method="post" class="row-form"><?=csrf_field()?><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><input type="number" min="1" max="<?=$stock?>" name="quantity" value="<?=e((string)$_SESSION['cart'][$p['product_id']])?>"><button class="btn small">Update</button></form><?php else:?><strong class="out-text">UNAVAILABLE</strong><?php endif;?></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$p['product_id']?>"><button class="link-danger">Remove</button></form></div><?php endforeach;?><?php endif;?></section><?php if($items):?><aside class="summary"><h2>Summary</h2><div><span>Available items</span><strong><?=money($subtotal)?></strong></div><?php if($blocked):?><div class="errors">Remove out-of-stock items before checkout.</div><?php else:?><a class="btn primary full" href="/shop/checkout.php">Proceed to checkout</a><?php endif;?></aside><?php endif;?></div><?php require __DIR__.'/../includes/footer.php';?>
